<script>
import{api,post,money,date}from '../api'
import{session}from '../session'
export default{data:()=>({session,event:null,summary:null,busy:true,error:'',review:{ticketId:'',rating:5,comment:''},reviewError:'',reviewSuccess:'',timer:null}),async mounted(){await this.load();this.timer=setInterval(()=>{if(document.visibilityState==='visible')this.refresh()},15000)},beforeUnmount(){clearInterval(this.timer)},methods:{money,date,async refresh(){try{this.event=await api('/catalog/events/'+this.$route.params.id)}catch(e){this.error=e.message}},async load(){this.busy=true;try{this.event=await api('/catalog/events/'+this.$route.params.id);this.summary=await api('/events/'+this.$route.params.id+'/reviews')}catch(e){this.error=e.message}finally{this.busy=false}},async sendReview(){this.reviewError='';this.reviewSuccess='';try{await post('/events/'+this.$route.params.id+'/reviews',this.review);this.reviewSuccess='Tu reseña fue registrada.';this.summary=await api('/events/'+this.$route.params.id+'/reviews');this.review.comment=''}catch(e){this.reviewError=e.message}}}}
</script>
<template><q-page class="container"><router-link to="/explorar" class="back-link">← Volver a explorar</router-link><q-banner v-if="error" class="error" role="alert">{{error}}</q-banner><div v-if="busy" class="empty"><q-spinner/> Cargando evento…</div><template v-if="event"><div class="detail-top"><div><div class="eyebrow">{{event.category}} · {{event.city}}</div><h1 class="page-heading">{{event.name}}</h1><q-badge color="primary">{{event.status}}</q-badge><p class="detail-description">{{event.description}}</p><div class="surface"><h3>Todo lo que necesitas saber</h3><p><strong>Cuándo:</strong> {{date(event.startDate)}}</p><p><strong>Dónde:</strong> {{event.venue}} · {{event.address}}, {{event.city}}</p><p><strong>Organiza:</strong> {{event.organizer}}</p></div></div><aside class="surface booking"><small>ENTRADA</small><h2>{{event.price===0?'Gratis':money(event.price,event.currency)}}</h2><p>{{event.availableSpots>0?event.availableSpots+' cupos disponibles':'Evento agotado'}}</p><q-linear-progress :value="Math.max(0,Math.min(1,event.availableSpots/event.capacity))" color="primary"/><p class="muted">Disponibilidad consultada cada 15 segundos mientras esta página está visible.</p><q-btn unelevated color="primary" no-caps class="full-width" :label="event.status==='Cancelado'?'Evento cancelado':event.availableSpots<=0?'Agotado':'Compra pendiente de integración'" disable/><p class="muted">La compra atómica se integra en el siguiente avance; no se procesa ningún pago.</p></aside></div><section class="surface reviews"><h2>Lo que cuenta la comunidad</h2><p v-if="summary">{{summary.averageRating}} / 5 · {{summary.totalReviews}} reseñas</p><article v-for="review in summary?.reviews||[]" :key="review.reviewId" class="review"><strong>{{review.rating}} / 5</strong><p>{{review.comment||'Sin comentario'}}</p><small>{{date(review.createdAt)}}</small></article><p v-if="!summary?.totalReviews">Este evento aún no tiene reseñas.</p><q-form v-if="session.user&&(event.status==='Finalizado'||new Date(event.endDate||event.startDate)<new Date())" @submit="sendReview" class="form-stack"><h3>Comparte tu experiencia</h3><p>Sólo se aceptan entradas utilizadas del evento finalizado; el servidor verifica el permiso.</p><q-input outlined v-model="review.ticketId" label="UUID de tu entrada utilizada" :rules="[v=>!!v||'Ingresa tu entrada']"/><q-rating v-model="review.rating" :max="5" color="secondary"/><q-input outlined type="textarea" v-model="review.comment" label="Tu comentario (opcional)" maxlength="1000"/><q-banner v-if="reviewError" class="error" role="alert">{{reviewError}}</q-banner><q-banner v-if="reviewSuccess" class="success" role="status">{{reviewSuccess}}</q-banner><q-btn type="submit" unelevated no-caps color="primary" label="Publicar reseña"/></q-form></section></template></q-page></template>
